rLib3bpA2Rt>AsanAllocModelAkChunksBlockCountC1?~~~~~~~~~~~~~~~C46Stdlib5Lists4List8nil_consC69OSSVerify5KrLib3bpA2Rt>AsanAllocModel;kNumClassesC1?~~~~~~~~~~~~~~~I69OSSVerify5KrLib3bpA2Rt>AsanAllocModel6region00C1?~~~~~~~~~~~~~~~C69OSSVerify5KrLib3bpA2Rt>AsanAllocModel:kSpaceSizeC1?~~~~~~~~~~~~~~~C69OSSVerify5KrLib3bpA2Rt8AllocRep8AFS_SIZEC1?~~~~~~~~~~~~~~~C69OSSVerify5KrLib3bpA2Rt>AsanAllocModel;kRegionSizeC1?~~~~~~~~~~~~~~~C69OSSVerify5KrLib3bpA2Rt5ASegs7AIMG_LOC1?~~~~~~~~~~~~~~~C69OSSVerify5KrLib3bpA2Rt9AllocRepX;AMODELX_preC69OSSVerify5KrLib3bpA2Rt9AllocRepX=akernel_pre_dC69OSSVerify5KrLib3bpA2Rt9AllocRepX<akernel_resxC4ELinuxProcessSemantics?LinuxProcessSem3RunAsegments_reservedC69OSSVerify5KrLib3bpA2Rt5ASegs5asegs".
Import ListNotations.
Open Scope Z_scope.
#[global] Unset Lia Cache. #[global] Unset Nia Cache. #[global] Unset Nra Cache.

Section HCW.
  Context {HCEIL : HeapCeil}.

Definition lg_L (L : list (word * word)) (pa nres nch : Z) : list (word * word) :=
  if nch =? nres then maps_subtract L (pa + 8 * nres) (pa + 8 * nres + 0x20000) else L.

Definition lg_cost (msz : Z) : Z := msz + 0x20000 + (msz / 32768 + 2) * 4096.

(* The new mapping (a, msz) is nonempty, so amaps_in_ledger's entries_nonzero conjunct
   survives the cons; its premise is amodelx_after's own section fact BND. *)
Lemma ml3_nz : forall (M0 : list (word * word)) (a msz pa : Z),
  7233536 <= a /\ a + msz <= aceil /\ 73728 <= msz /\ 7233536 <= pa /\ pa + 8388608 <= aceil
    /\ 2148355072 <= sh a /\ sh a + msz / 8 <= (sh aceil) /\ 8 * (msz / 8) = msz ->
  entries_nonzero M0 -> entries_nonzero ((wz a, wz msz) :: M0).
Proof.
  intros M0 a msz pa (B1 & B2 & B3 & _) NZ. apply entries_nonzero_cons; [| exact NZ].
  acb. unfold wz. rewrite unsigned_lit by lia. lia.
Qed.

Section ModelAfterLarge.
  Variables (s : ast) (mo mo2 : Model) (a size : Z) (d : depot).
  Let st := a_st s.
  Let pa := a_pa s.
  Let r := compute_req size.
  Let needed := rq_needed r.
  Let msz := round_up needed kPageSize + kPageSize.
  Let nch := zlen (as_sec st).
  Let nres := as_n_reserved st.
  Let st2 := large_state st a size.
  Let Wsh : word * word := (wz (sh a), wz (msz / 8)).
  Let L2 := lg_L (a_L s) pa nres nch.
  Let AL2 := a_AL s - lg_cost msz.
  Let s2 := mkAst st2 (a_thr s) (a_ctx s) (a_fsb s) L2 (Wsh :: a_S s) (a_Zr s) AL2 (a_top s) (a_bot s).

  Hypothesis AMX : AMODELX s mo.
  Hypothesis DCOV : depot_cov d mo.
  Hypothesis SZ : 64512 < size < 2^32.
  Hypothesis AR : aapp a msz /\ a + msz <= aceil /\ a mod 4096 = 0.
  Hypothesis FREE : region_free (vm_reserved (m_vmmaps mo) ++ vm_maps (m_vmmaps mo)) (wz a) (wz msz) = true.
  Hypothesis LM : rsub (a_L s) (vm_maps (m_vmmaps mo)).
  Hypothesis NWL : entries_nowrap (a_L s).
  Hypothesis ALLOW : lg_cost msz <= a_AL s.
  Hypothesis PAR : aapp pa kPtrArrayReserve /\ pa + kPtrArrayReserve <= aceil.
  Hypothesis NCH : 0 <= nch <= nres /\ nres + 16384 <= 2^20.
  Hypothesis MO : as_model mo a msz pa nres (nch =? nres) mo2.

  Let ARE : 7233536 <= a /\ a + msz <= aceil. Proof. pose proof (proj1 AR) as X. clear - X. aunf. lia. Qed.
  Let PAE : 7233536 <= pa /\ pa + kPtrArrayReserve <= aceil. Proof. exact (aapp_env _ _ (proj1 PAR) ltac:(clear; hci; unfold kPtrArrayReserve; lia)). Qed.
  Let RQ := large_req size SZ.

  Let GEO : size + 8 <= needed - 4088 /\ needed <= size + 4104 /\ needed + 4096 <= msz /\ msz < needed + 8192 /\ needed mod 8 = 0 /\ msz mod 4096 = 0 /\ a mod 4096 = 0.
  Proof.
    apply (large_geo st a size SZ). destruct AR as (_ & _ & AL). unfold kPageSize. change (4096 - 1) with (Z.ones 12). rewrite Z.land_ones by lia. exact AL.
  Qed.

  Let BND : 7233536 <= a /\ a + msz <= aceil /\ 73728 <= msz /\ 7233536 <= pa /\ pa + 8388608 <= aceil
            /\ 2148355072 <= sh a /\ sh a + msz / 8 <= (sh aceil) /\ 8 * (msz / 8) = msz.
  Proof.
    destruct AR as (A1 & A2 & A3). pose proof GEO as (G1 & G2 & G3 & G4 & G5 & G6 & G7). destruct PAR as [P1 P2].
    pose proof (aapp_sh_env_div _ _ A1 ltac:(clear - G1 G3 SZ; lia)) as ASH.
    apply aapp_env in A1; [| clear - G1 G3 SZ; lia]. apply aapp_env in P1; [| unfold kPtrArrayReserve; clear; lia].
    acb. unfold AHI_LO, kPtrArrayReserve in *. subst pa.
    unfold round_up, round_down, sh, ASHADOW_BASE in *. repeat split; try lia; Z.div_mod_to_equations; lia.
  Qed.

  Let PBAND : pa + 8388608 <= 2147446784 \/ 17594333495296 <= pa.
  Proof. pose proof (aapp_lit _ _ (proj1 PAR)) as L. unfold kPtrArrayReserve in L. exact L. Qed.

  (* LPS 727298f3: [akernel] is [akernel_pre /\ akernel_resx] ([AllocRepX]).  The recorded proof
     below builds [AMODELX_pre]; in it the goal's [AMODELX] became [AMODELX_pre], the rebuilt
     kernel conjunction's [akernel] became [akernel_pre_d], the destructed kernel invariant is
     [proj1] of the hypothesis, and the first conjunct's list is [segments_reserved asegs];
     decoded, the two terms differ there only.  [amodelx_after] adds [akernel_resx], which the
     step keeps (the same ledger and bases). *)
